<?php
declare(strict_types=1);

require_once __DIR__ . '/includes/init.php';
require_once __DIR__ . '/csrf_helper.php';
require_once __DIR__ . '/includes/public_velodrome.php';
if (!isset($_SESSION['trener_id']) || !roleAtLeast('admin')) {
    header('Location: login.php');
    exit;
}
function publicVelodromeAdminH(mixed $value): string { return htmlspecialchars((string)$value,ENT_QUOTES|ENT_SUBSTITUTE,'UTF-8'); }
$errors=[];$success='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    if(!csrf_verify((string)($_POST['csrf_token']??'')))$errors[]='Formulář vypršel.';
    else try{$action=(string)($_POST['action']??'create_slot');if($action==='manual_confirm'){$result=publicVelodromeManualConfirm($pdo,(int)($_POST['reservation_id']??0),(int)$_SESSION['trener_id'],(string)($_POST['note']??''),($_POST['confirm_payment']??'')==='1');$success=$result['changed']?'Platba a rezervace byly potvrzeny.':'Rezervace už byla potvrzena.';}else{$result=publicVelodromeCreateSlot($pdo,(int)$_SESSION['trener_id'],(string)($_POST['date']??''),(string)($_POST['starts_at']??''),(string)($_POST['ends_at']??''),(int)($_POST['capacity']??0),($_POST['exclusive']??'')==='1',(int)($_POST['price_minor']??0));$success='Veřejný termín #'.$result['id'].' byl vytvořen.';}}catch(InvalidArgumentException|PublicVelodromeException $exception){$errors[]=$exception->getMessage();}
}
$slots=publicVelodromeSlots($pdo);$reservations=publicVelodromeAdminReservations($pdo);
?>
<!doctype html><html lang="cs"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Veřejné hodiny velodromu</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"></head><body class="bg-light"><?php include __DIR__.'/hlavicka.php';?><main class="container py-4" style="max-width:1000px"><h1 class="h4">Veřejné hodiny velodromu</h1><?php foreach($errors as$error):?><div class="alert alert-danger"><?=publicVelodromeAdminH($error)?></div><?php endforeach;?><?php if($success!==''):?><div class="alert alert-success"><?=publicVelodromeAdminH($success)?></div><?php endif;?><div class="card border-0 shadow-sm mb-4"><div class="card-body"><form method="post" class="row g-3"><?=csrf_field()?><input type="hidden" name="action" value="create_slot"><div class="col-md-3"><label class="form-label">Datum</label><input class="form-control" type="date" name="date" required></div><div class="col-md-2"><label class="form-label">Od</label><input class="form-control" type="time" name="starts_at" required></div><div class="col-md-2"><label class="form-label">Do</label><input class="form-control" type="time" name="ends_at" required></div><div class="col-md-2"><label class="form-label">Kapacita</label><input class="form-control" type="number" name="capacity" min="1" max="1000" value="1" required></div><div class="col-md-2"><label class="form-label">Cena v haléřích</label><input class="form-control" type="number" name="price_minor" min="0" value="0" required></div><div class="col-md-4 form-check ms-2"><input class="form-check-input" type="checkbox" name="exclusive" value="1" id="exclusive"><label class="form-check-label" for="exclusive">Výhradní rezervace celého slotu</label></div><div class="col-md-3 d-grid"><button class="btn btn-primary">Vypsat hodinu</button></div></form></div></div><div class="table-responsive mb-4"><table class="table"><thead><tr><th>Termín</th><th>Režim</th><th>Obsazeno</th><th>Cena</th></tr></thead><tbody><?php foreach($slots as$slot):?><tr><td><?=publicVelodromeAdminH($slot['datum'].' '.$slot['cas_od'].'–'.$slot['cas_do'])?></td><td><?=$slot['public_exclusive_booking']?'výhradní':'sdílený'?></td><td><?=$slot['reserved_count']?> / <?=$slot['effective_capacity']?></td><td><?=number_format((float)$slot['cena_kc'],2,',',' ')?> Kč</td></tr><?php endforeach;?></tbody></table></div><div class="card border-0 shadow-sm"><div class="card-header bg-white fw-semibold">Ruční potvrzení placených rezervací</div><div class="card-body"><?php foreach($reservations as$reservation):?><div class="border-bottom py-2"><div><strong><?=publicVelodromeAdminH($reservation['prijmeni'].' '.$reservation['jmeno'])?></strong> · <?=publicVelodromeAdminH($reservation['datum'].' '.$reservation['cas_od'])?> · <?=number_format((float)$reservation['cena_kc'],2,',',' ')?> Kč · <?=publicVelodromeAdminH($reservation['stav'])?><?=$reservation['zaplaceno']?' · zaplaceno':''?></div><?php if($reservation['stav']==='ceka'&&!(int)$reservation['zaplaceno']&&(float)$reservation['cena_kc']>0):?><form method="post" class="row g-2 mt-1"><?=csrf_field()?><input type="hidden" name="action" value="manual_confirm"><input type="hidden" name="reservation_id" value="<?=(int)$reservation['id']?>"><div class="col-md-6"><input class="form-control form-control-sm" name="note" maxlength="1000" required placeholder="Důvod a reference přijaté platby"></div><div class="col-md-3 form-check"><input class="form-check-input" type="checkbox" name="confirm_payment" value="1" id="pay-<?=(int)$reservation['id']?>" required><label class="form-check-label" for="pay-<?=(int)$reservation['id']?>">Potvrzuji přijetí platby</label></div><div class="col-md-3 d-grid"><button class="btn btn-success btn-sm">Potvrdit platbu</button></div></form><?php endif;?></div><?php endforeach;?></div></div></main></body></html>
